// The stateful core: a pure transition function over one job's state.
// The host keeps one JobState per id and routes every command through step().
// spec/jobs.spec.cjs mirrors this function as a SAM module for polygraph.

import type { JobView } from '../host.ts';

export type Status = JobView['status'];

export interface JobState {
  status: Status;
  tries: number;
  maxTries: number;
}

export type Command = 'claim' | 'succeed' | 'fail' | 'lost' | 'cancel' | 'hold' | 'release';

export type StepResult = { ok: true; next: JobState } | { ok: false; reason: string };

export const MIN_TRIES = 1;
export const MAX_TRIES = 3;

export function create(maxTries: number): StepResult {
  if (!Number.isInteger(maxTries) || maxTries < MIN_TRIES || maxTries > MAX_TRIES) {
    return { ok: false, reason: `maxTries must be an integer from ${MIN_TRIES} to ${MAX_TRIES}` };
  }
  return { ok: true, next: { status: 'queued', tries: 0, maxTries } };
}

/** A worker's try ended without success (fail or lost). */
function tryEnded(s: JobState): StepResult {
  if (s.status === 'running') {
    const status: Status = s.tries < s.maxTries ? 'queued' : 'failed';
    return { ok: true, next: { ...s, status } };
  }
  if (s.status === 'cancelling') return { ok: true, next: { ...s, status: 'cancelled' } };
  return { ok: false, reason: `job is ${s.status}, not running or cancelling` };
}

export function step(s: JobState, command: Command): StepResult {
  switch (command) {
    case 'claim':
      if (s.status !== 'queued') return { ok: false, reason: `job is ${s.status}, not queued` };
      if (s.tries >= s.maxTries) return { ok: false, reason: 'no tries left' };
      return { ok: true, next: { ...s, status: 'running', tries: s.tries + 1 } };
    case 'succeed':
      if (s.status === 'running' || s.status === 'cancelling') {
        return { ok: true, next: { ...s, status: 'succeeded' } };
      }
      return { ok: false, reason: `job is ${s.status}, not running or cancelling` };
    case 'fail':
    case 'lost':
      return tryEnded(s);
    case 'cancel':
      if (s.status === 'queued') return { ok: true, next: { ...s, status: 'cancelled' } };
      if (s.status === 'running') return { ok: true, next: { ...s, status: 'cancelling' } };
      return { ok: false, reason: `job is ${s.status}, cannot be cancelled` };
  }
}

import type { CreateHost, Host, JobView, Outcome } from '../host.ts';
import { create, step } from './jobs.ts';
import type { Command, JobState, StepResult } from './jobs.ts';

const createHost: CreateHost = async () => {
  const jobs = new Map<string, JobState>();

  const commit = (job: string, r: StepResult): Outcome => {
    if (!r.ok) return { ok: false, reason: r.reason };
    jobs.set(job, r.next);
    return { ok: true };
  };

  const run = async (job: string, command: Command): Promise<Outcome> => {
    const s = jobs.get(job);
    if (!s) return { ok: false, reason: `no job ${JSON.stringify(job)}` };
    return commit(job, step(s, command));
  };

  const host: Host = {
    async submit(job, maxTries) {
      if (jobs.has(job)) return { ok: false, reason: `job ${JSON.stringify(job)} already exists` };
      return commit(job, create(maxTries));
    },
    claim: (job) => run(job, 'claim'),
    succeed: (job) => run(job, 'succeed'),
    fail: (job) => run(job, 'fail'),
    lost: (job) => run(job, 'lost'),
    cancel: (job) => run(job, 'cancel'),
    async job(job): Promise<JobView | null> {
      const s = jobs.get(job);
      return s ? { status: s.status, tries: s.tries, maxTries: s.maxTries } : null;
    },
  };
  return host;
};

export default createHost;

'use strict';

// SAM v2 strict-profile spec of src/jobs.ts (create + step), for ONE job id.
// Jobs are independent (the host keeps one JobState per id in a Map), so one
// job is the whole stateful core. status 'none' stands for "never submitted":
// every command but SUBMIT is refused there, as the host refuses an unknown id.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = { status: 'none', tries: 0, maxTries: 0 };

const noData = () => ({ action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] });

// A worker's try ended without success (FAIL or LOST): src/jobs.ts tryEnded().
const tryEnded = (model) => (proposal, { reject, next, unchanged }) => {
  if (model.status === 'running') {
    next.status = model.tries < model.maxTries ? 'queued' : 'failed';
    unchanged('tries', 'maxTries');
    return;
  }
  if (model.status === 'cancelling') {
    next.status = 'cancelled';
    unchanged('tries', 'maxTries');
    return;
  }
  return reject('not-running-or-cancelling');
};

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      tries: { type: 'number' },
      maxTries: { type: 'number' },
    },
    actions: {
      SUBMIT: {
        action: (data = {}) => ({ ...data }),
        schema: { maxTries: { type: 'number' } },
        domain: [{ maxTries: 0 }, { maxTries: 1 }, { maxTries: 2 }, { maxTries: 3 }, { maxTries: 4 }, { maxTries: 1.5 }],
      },
      CLAIM: noData(),
      SUCCEED: noData(),
      FAIL: noData(),
      LOST: noData(),
      CANCEL: noData(),
    },
    acceptors: {
      SUBMIT: (model) => (proposal, { reject, next }) => {
        if (model.status !== 'none') return reject('job-exists');
        const m = proposal.maxTries;
        if (!Number.isInteger(m) || m < 1 || m > 3) return reject('maxTries-out-of-range');
        next.status = 'queued';
        next.tries = 0;
        next.maxTries = m;
      },
      CLAIM: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'queued') return reject('not-queued');
        if (model.tries >= model.maxTries) return reject('no-tries-left');
        next.status = 'running';
        next.tries = model.tries + 1;
        unchanged('maxTries');
      },
      SUCCEED: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'running' && model.status !== 'cancelling') return reject('not-running-or-cancelling');
        next.status = 'succeeded';
        unchanged('tries', 'maxTries');
      },
      FAIL: (model) => tryEnded(model),
      LOST: (model) => tryEnded(model),
      CANCEL: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'queued') next.status = 'cancelled';
        else if (model.status === 'running') next.status = 'cancelling';
        else return reject('not-cancellable');
        unchanged('tries', 'maxTries');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  SUBMIT: (data = {}) => intents.SUBMIT(data),
  CLAIM: (data = {}) => intents.CLAIM(data),
  SUCCEED: (data = {}) => intents.SUCCEED(data),
  FAIL: (data = {}) => intents.FAIL(data),
  LOST: (data = {}) => intents.LOST(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
};

module.exports = { instance, init, actions, getState, setState };

