  "behavioralRules": [
    { "name": "cancelling-succeed-wins", "note": "SUCCEED on a cancelling job: the work was done, the job becomes succeeded" },
    { "name": "cancelling-fail-cancels", "note": "FAIL/LOST on a cancelling job: it becomes cancelled, never retried" },
    { "name": "retry-while-tries-left", "note": "FAIL/LOST on a running job requeues it while tries < maxTries, else failed" }
  ],
  "noOpRule": "A refused command changes nothing: post == pre, observable as reject(reason)."
