import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const ok = { ok: true };
const refused = (o: { ok: boolean }) => assert.equal(o.ok, false);

test('submit validates maxTries and duplicates', async () => {
  const h = await createHost();
  for (const m of [0, 4, 1.5, NaN, -1]) refused(await h.submit('a', m));
  assert.equal(await h.job('a'), null);
  assert.deepEqual(await h.submit('a', 2), ok);
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 0, maxTries: 2 });
  refused(await h.submit('a', 1));
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 0, maxTries: 2 });
});

test('unknown job refused', async () => {
  const h = await createHost();
  for (const c of ['claim', 'succeed', 'fail', 'lost', 'cancel'] as const) refused(await h[c]('x'));
  assert.equal(await h.job('x'), null);
});

test('retries until limit, then failed', async () => {
  const h = await createHost();
  await h.submit('j', 2);
  assert.deepEqual(await h.claim('j'), ok);
  refused(await h.claim('j'));
  assert.deepEqual(await h.fail('j'), ok);
  assert.deepEqual(await h.job('j'), { status: 'queued', tries: 1, maxTries: 2 });
  await h.claim('j');
  assert.deepEqual(await h.lost('j'), ok);
  assert.deepEqual(await h.job('j'), { status: 'failed', tries: 2, maxTries: 2 });
  refused(await h.claim('j'));
  refused(await h.cancel('j'));
  refused(await h.fail('j'));
});

test('succeed', async () => {
  const h = await createHost();
  await h.submit('j', 1);
  refused(await h.succeed('j'));
  await h.claim('j');
  assert.deepEqual(await h.succeed('j'), ok);
  assert.deepEqual(await h.job('j'), { status: 'succeeded', tries: 1, maxTries: 1 });
  refused(await h.succeed('j'));
});

test('cancel queued and running', async () => {
  const h = await createHost();
  await h.submit('q', 3);
  assert.deepEqual(await h.cancel('q'), ok);
  assert.equal((await h.job('q'))!.status, 'cancelled');
  refused(await h.cancel('q'));

  await h.submit('r', 3);
  await h.claim('r');
  assert.deepEqual(await h.cancel('r'), ok);
  assert.equal((await h.job('r'))!.status, 'cancelling');
  refused(await h.cancel('r'));
  refused(await h.claim('r'));
  assert.deepEqual(await h.fail('r'), ok);
  assert.deepEqual(await h.job('r'), { status: 'cancelled', tries: 1, maxTries: 3 });

  await h.submit('s', 3);
  await h.claim('s');
  await h.cancel('s');
  assert.deepEqual(await h.succeed('s'), ok);
  assert.deepEqual(await h.job('s'), { status: 'succeeded', tries: 1, maxTries: 3 });

  await h.submit('l', 1);
