  status: Status;
  tries: number;
  maxTries: number;
}

export type Command = 'claim' | 'succeed' | 'fail' | 'failPermanently' | 'lost' | 'cancel' | 'hold' | 'release';

export type StepResult = { ok: true; next: JobState } | { ok: false; reason: string };

export const MIN_TRIES = 1;
export const MAX_TRIES = 3;

