// Differential check: the polygraph spec (spec/jobs.spec.cjs) and the real
// core (src/jobs.ts) agree on every (state, action, data) over the spec's domain.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { loadSpec } from '../tools/polygraph/scripts/load-spec.mjs';
import { create, step } from '../src/jobs.ts';
import type { Command, JobState } from '../src/jobs.ts';

const spec: any = await loadSpec('spec/jobs.spec.cjs');
const STATUSES = ['none', 'queued', 'running', 'cancelling', 'succeeded', 'failed', 'cancelled', 'held'];
const ACTIONS: Record<string, Command | 'submit'> = { SUBMIT: 'submit', CLAIM: 'claim', SUCCEED: 'succeed', FAIL: 'fail', FAIL_PERMANENTLY: 'failPermanently', LOST: 'lost', CANCEL: 'cancel', HOLD: 'hold', RELEASE: 'release' };

function specStep(pre: any, action: string, data: any) {
  spec.init();
  spec.setState(pre);
  spec.actions[action](data);
  return spec.getState();
}

function implStep(pre: any, action: string, data: any) {
  const cmd = ACTIONS[action];
  if (pre.status === 'none') {
    if (cmd !== 'submit') return pre;
    const r = create(data.maxTries);
    return r.ok ? r.next : pre;
  }
  if (cmd === 'submit') return pre; // the host refuses a duplicate id
  const r = step(pre as JobState, cmd);
  return r.ok ? r.next : pre;
}

test('spec matches src/jobs.ts on every state and action', () => {
  let n = 0;
  for (const status of STATUSES) for (let maxTries = 0; maxTries <= 3; maxTries++) for (let tries = 0; tries <= maxTries; tries++) {
    if ((status === 'none') !== (maxTries === 0)) continue;
    const pre = { status, tries, maxTries };
    for (const action of Object.keys(ACTIONS)) {
      const datas = action === 'SUBMIT' ? [0, 1, 2, 3, 4, 1.5].map((m) => ({ maxTries: m })) : [{}];
      for (const data of datas) {
        assert.deepEqual(specStep(pre, action, data), implStep(pre, action, data), `${JSON.stringify(pre)} ${action} ${JSON.stringify(data)}`);
        n++;
      }
    }
  }
  assert.ok(n > 100);
});

